#include "modules/fem_mean_api.h"
#include "modules/fem_parallel_api.h"
#include "runtime/thread_budget.hpp"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <numbers>
#include <string>
#include <vector>

namespace {
int checks=0,failures=0;void expect(bool yes,const char* message){++checks;if(!yes){++failures;std::cerr<<"FAIL: "<<message<<'\n';}}
struct Mesh {std::vector<double> points;std::vector<uint64_t> faces,boundaries;Mesh(unsigned n=4){for(unsigned y=0;y<=n;++y)for(unsigned x=0;x<=n;++x){points.push_back(double(x)/n);points.push_back(double(y)/n);}auto id=[&](unsigned x,unsigned y){return uint64_t(y*(n+1)+x+1);};for(unsigned y=0;y<n;++y)for(unsigned x=0;x<n;++x){const auto a=id(x,y),b=id(x+1,y),c=id(x,y+1),d=id(x+1,y+1);faces.insert(faces.end(),{a,b,d,a,d,c});}for(unsigned k=0;k<n;++k)boundaries.insert(boundaries.end(),{id(0,k),id(0,k+1),1,id(n,k),id(n,k+1),2,id(k,0),id(k+1,0),3,id(k,n),id(k+1,n),4});}
    void append(const Mesh& other,double offset){const auto count=points.size()/2;for(std::size_t k=0;k<other.points.size();k+=2){points.push_back(other.points[k]+offset);points.push_back(other.points[k+1]);}for(auto vertex:other.faces)faces.push_back(vertex+count);for(std::size_t k=0;k<other.boundaries.size();k+=3)boundaries.insert(boundaries.end(),{other.boundaries[k]+count,other.boundaries[k+1]+count,other.boundaries[k+2]+4});}
};
int forcing(void*,double x,double,double* value,char*,uint64_t){*value=std::numbers::pi*std::numbers::pi*std::cos(std::numbers::pi*x);return 0;}
int exact(void* raw,double x,double,double* value,char*,uint64_t){*value=std::cos(std::numbers::pi*x)+(raw?*static_cast<double*>(raw):0);return 0;}
int incompatible(void*,double,double,double* value,char*,uint64_t){*value=1;return 0;}
int cancelling(void*,double x,double,double* value,char*,uint64_t){*value=x<1.5?1:-1;return 0;}
int zero(void*,double,double,double* value,char*,uint64_t){*value=0;return 0;}
struct Host {penta::runtime::ParallelSettings settings;penta::runtime::ParallelStatistics statistics;
    static int parallel(void* raw,uint64_t count,uint64_t cost,penta_numeric_range_task_v1 task,void* data,char* error,uint64_t capacity){auto& self=*static_cast<Host*>(raw);penta::runtime::ParallelStatistics observed;std::string message;const auto status=penta::runtime::ThreadBudget::instance().run(count,cost,task,data,self.settings,{},observed,message);self.statistics.parallelCalls+=observed.parallelCalls;self.statistics.threadsUsed=std::max(self.statistics.threadsUsed,observed.threadsUsed);if(error&&capacity){const auto size=std::min<uint64_t>(capacity-1,message.size());std::copy_n(message.data(),size,error);error[size]=0;}return status;}
};
struct Result {int status;std::string error;penta_fem_mean_result_v1 report{};std::vector<double> coordinates,values,visualCoordinates,visualValues;std::vector<uint64_t> visualFaces;penta::runtime::ParallelStatistics statistics;};
Result run(const Mesh& mesh,unsigned order,double mean,penta_fem_field_v1 source=forcing,bool constrained=true,double reaction=0,unsigned threads=1){penta_fem_mean_request_v1 q{};q.abi_version=PENTA_FEM_MEAN_ABI_V1;q.target_mean=mean;q.compatibility_tolerance=1e-10;auto& base=q.base;base.struct_size=sizeof(q);base.order=order;base.visualization_refinement=2;base.vertices=mesh.points.size()/2;base.triangles=mesh.faces.size()/3;base.boundaries=mesh.boundaries.size()/3;base.points=mesh.points.data();base.faces=mesh.faces.data();base.boundary_tags=mesh.boundaries.data();base.dirichlet_count=0;base.diffusion_constant=1;base.reaction_constant=reaction;base.relative_tolerance=1e-10;base.absolute_tolerance=1e-11;base.max_seconds=30;base.max_iterations=10000;base.max_work=100000000;base.max_bytes=256*1024*1024;base.forcing=source;base.exact=exact;base.exact_context=&mean;
    const uint64_t local=(order+1)*(order+2)/2,dofs=base.vertices+3*base.triangles*(order-1)+(order>=3?base.triangles*(order-1)*(order-2)/2:0),vertices=base.triangles*6,triangles=base.triangles*4;Result result;result.coordinates.resize(dofs*2);result.values.resize(dofs);result.visualCoordinates.resize(vertices*2);result.visualValues.resize(vertices);result.visualFaces.resize(triangles*3);auto& out=result.report.base;out.struct_size=sizeof(result.report);out.dof_capacity=dofs;out.vertex_capacity=vertices;out.triangle_capacity=triangles;out.dof_coordinates=result.coordinates.data();out.dof_values=result.values.data();out.visualization_coordinates=result.visualCoordinates.data();out.visualization_values=result.visualValues.data();out.visualization_faces=result.visualFaces.data();(void)local;Host context;context.settings.threads=threads;context.settings.serialThreshold=1;penta_fem_parallel_host_v1 host{};host.base={sizeof(host),PENTA_FEM_ABI_V1,&context,nullptr,nullptr};host.threads_requested=host.threads_granted=threads;host.parallel_for=Host::parallel;char error[1024]{};penta::runtime::ThreadBudget::instance().withReservation([&]{if(constrained)result.status=penta_fem_mean_query_v1(PENTA_FEM_MEAN_ABI_V1)->solve(&host.base,&q,&result.report,error,sizeof(error));else result.status=penta_fem_query_v1(PENTA_FEM_ABI_V1)->solve(&host.base,&base,&out,error,sizeof(error));});result.error=error;result.statistics=context.statistics;return result;}
}
int main(){
    try{
        Mesh mesh(4);auto linear=run(mesh,1,0),cubic=run(mesh,3,0);if(linear.status)std::cerr<<linear.error<<'\n';if(cubic.status)std::cerr<<cubic.error<<'\n';expect(linear.status==0&&cubic.status==0,"Mean-constrained pure-Neumann P1/P3 MFEM solves complete.");if(!linear.status&&!cubic.status){expect(linear.report.base.converged&&cubic.report.base.converged,"Pinned and recovered physical residuals satisfy their tolerances.");expect(cubic.report.base.l2_error<linear.report.base.l2_error*.02&&cubic.report.base.l2_error<1e-4,"High-order Neumann solution converges against an independent cosine manufactured solution.");expect(cubic.report.maximum_mean_error<1e-12&&cubic.report.compatibility_residual<1e-12&&cubic.report.nullspace_components==1,"Mean and forcing compatibility are verified independently of gauge pinning.");}
        auto shifted=run(mesh,3,1.5);expect(shifted.status==0&&shifted.report.maximum_mean_error<1e-12,"A nonzero prescribed mean is applied after recovering the nullspace gauge.");if(!shifted.status)expect(shifted.report.base.l2_error<1e-4,"Adding a requested mean retains the manufactured high-order field.");
        auto bad=run(mesh,2,0,incompatible);expect(bad.status==PENTA_NUMERIC_ARGUMENT&&bad.error.find("compatibility")!=std::string::npos,"Incompatible nonzero-integral forcing is rejected before solving.");
        Mesh disconnected(2);disconnected.append(Mesh(2),2);auto separate=run(disconnected,2,.75);expect(separate.status==0&&separate.report.nullspace_components==2&&separate.report.maximum_mean_error<1e-12,"Disconnected Neumann components receive independent compatibility/gauge/mean constraints.");auto biased=run(disconnected,2,0,cancelling);expect(biased.status==PENTA_NUMERIC_ARGUMENT,"Global cancellation cannot hide incompatible forcing on each disconnected component.");
        auto unspecified=run(mesh,2,0,forcing,false);expect(unspecified.status==PENTA_NUMERIC_ARGUMENT,"The original ABI still requires an explicit gauge for a singular Neumann problem.");auto coercive=run(mesh,2,0,zero,false,1);expect(coercive.status==0&&coercive.report.base.converged,"A positive constant reaction yields a nonsingular unanchored legacy FEM problem.");expect(penta_fem_mean_query_v1(99)==nullptr,"Unsupported mean-capability ABI versions fail explicitly.");
        Mesh larger(8);auto serial=run(larger,3,1.5),parallel=run(larger,3,1.5,forcing,true,0,2);if(parallel.status)std::cerr<<parallel.error<<'\n';expect(serial.status==0&&parallel.status==0&&parallel.report.base.converged,"High-order mean-constrained FEM runs with shared parallel CSR-CG.");if(!serial.status&&!parallel.status){double difference=0;for(std::size_t d=0;d<parallel.report.base.dofs;++d)difference=std::max(difference,std::abs(serial.values[d]-parallel.values[d]));expect(difference<1e-7&&parallel.report.base.l2_error<1e-5,"Parallel high-order solution agrees with serial MFEM and the manufactured field.");expect(parallel.statistics.parallelCalls>0&&parallel.statistics.threadsUsed<=2,"FEM matvec/preconditioning/dot kernels use the granted shared CPU budget.");}
    }catch(const std::exception& error){++failures;std::cerr<<"Unexpected exception: "<<error.what()<<'\n';}
    std::cout<<checks<<" FEM mean kernel checks, "<<failures<<" failures\n";return failures?1:0;
}
